-- Run once on a fresh Supabase project. Provision accounts through the SQL editor.
-- Configuration is supplied from src/config.ts by a pre-provisioned owner.
create table public.studio_owners(user_id uuid primary key references auth.users on delete cascade);
create table public.profiles(id uuid primary key references auth.users on delete cascade, name text not null, role text not null check(role in ('OWNER','ADMIN','TEAM MEMBER','CLIENT')), client_id uuid);
create table public.studio_settings(id boolean primary key default true check(id),data jsonb not null);
create table public.clients(id uuid primary key,data jsonb not null,portal_token uuid not null unique);
alter table public.profiles add constraint profile_client_fk foreign key(client_id) references public.clients;
create table public.projects(id uuid primary key,client_id uuid not null references public.clients,data jsonb not null);
create table public.project_members(project_id uuid references public.projects on delete cascade,user_id uuid references public.profiles,primary key(project_id,user_id));
create table public.tasks(id uuid primary key,project_id uuid not null references public.projects,assignee uuid not null references public.profiles,data jsonb not null);
create table public.deliverables(id uuid primary key,project_id uuid not null references public.projects,data jsonb not null);
create table public.deliverable_versions(id uuid primary key,deliverable_id uuid not null references public.deliverables,data jsonb not null);
create unique index unique_version_label on public.deliverable_versions(deliverable_id,lower(data->>'label'));
create table public.comments(id uuid primary key,project_id uuid not null references public.projects,deliverable_id uuid references public.deliverables,task_id uuid references public.tasks,visibility text not null check(visibility in ('Internal','Client-visible')),data jsonb not null);
create table public.approvals(id uuid primary key,project_id uuid not null references public.projects,version_id uuid not null references public.deliverable_versions,client_id uuid not null references public.clients,data jsonb not null);
create table public.invoices(id uuid primary key,client_id uuid not null references public.clients,project_id uuid not null references public.projects,token uuid not null unique,number text not null unique,data jsonb not null);
create table public.invoice_items(id uuid primary key,invoice_id uuid not null references public.invoices,data jsonb not null);
create table public.payments(id uuid primary key,invoice_id uuid not null references public.invoices,data jsonb not null,check((data->>'amount')::numeric>0));
create table public.time_entries(id uuid primary key,project_id uuid not null references public.projects,task_id uuid references public.tasks,user_id uuid not null references public.profiles,invoice_id uuid references public.invoices,data jsonb not null,check((data->>'seconds')::numeric>0));
create table public.timers(id uuid primary key,project_id uuid not null references public.projects,task_id uuid references public.tasks,user_id uuid not null unique references public.profiles,data jsonb not null);
create table public.activity_logs(id uuid primary key,project_id uuid references public.projects,data jsonb not null);
create table public.notification_dismissals(user_id uuid references public.profiles,key text not null,primary key(user_id,key));
create table public.operation_requests(user_id uuid references public.profiles,request_id uuid,result jsonb,primary key(user_id,request_id));

create function public.studio_role() returns text language sql stable security definer set search_path=public,pg_temp as $$select role from public.profiles where id=auth.uid()$$;
create function public.studio_admin() returns boolean language sql stable security definer set search_path=public,pg_temp as $$select coalesce(public.studio_role() in ('OWNER','ADMIN'),false)$$;
create function public.studio_project_access(p_id uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select public.studio_admin() or (public.studio_role()='TEAM MEMBER' and exists(select 1 from public.project_members where project_id=p_id and user_id=auth.uid()))$$;
create function public.studio_client_access(p_id uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from public.profiles where id=auth.uid() and role='CLIENT' and client_id=p_id)$$;
do $$declare t text;begin foreach t in array array['studio_owners','profiles','studio_settings','clients','projects','project_members','tasks','deliverables','deliverable_versions','comments','approvals','invoices','invoice_items','payments','time_entries','timers','activity_logs','notification_dismissals','operation_requests'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);end loop;end$$;
-- Private management reads are exposed through explicitly scoped RPCs, not direct table grants.
create function public.studio_require_admin() returns void language plpgsql security definer set search_path=public,pg_temp as $$begin if not public.studio_admin() then raise exception 'Owner or admin access required.';end if;end$$;
create function public.studio_require_project(p_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin if not public.studio_project_access(p_id) then raise exception 'Project access denied.';end if;end$$;
create function public.studio_text(v text,label text,minlen integer default 0,maxlen integer default 3000) returns text language plpgsql as $$begin if v is null or length(trim(v))<minlen or length(v)>maxlen then raise exception 'Invalid %.',label;end if;return trim(v);end$$;
create function public.studio_num(v numeric,label text,maxval numeric default 1000000000000) returns numeric language plpgsql as $$begin if v is null or v<0 or v>maxval then raise exception 'Invalid %.',label;end if;return v;end$$;
create function public.studio_log(p_id uuid,msg text) returns void language sql security definer set search_path=public,pg_temp as $$insert into public.activity_logs values(gen_random_uuid(),p_id,jsonb_build_object('id',gen_random_uuid(),'projectId',coalesce(p_id::text,''),'message',msg,'actor',(select name from profiles where id=auth.uid()),'createdAt',now()))$$;
create function public.studio_invoice_total(p_id uuid) returns numeric language sql stable security definer set search_path=public,pg_temp as $$select round((s-(i.data->>'discount')::numeric)*(1+(i.data->>'taxRate')::numeric/100)) from invoices i cross join lateral(select coalesce(sum(round((data->>'quantity')::numeric*(data->>'rate')::numeric)),0) s from invoice_items where invoice_id=i.id) q where i.id=p_id$$;
create function public.studio_sync(p_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare stages jsonb;stage text;allapproved boolean;begin select data->'workflow' into stages from studio_settings;select exists(select 1 from deliverables where project_id=p_id) and not exists(select 1 from deliverables d where d.project_id=p_id and coalesce((select v.data->>'status' from deliverable_versions v where v.deliverable_id=d.id order by (v.data->>'createdAt')::timestamptz desc limit 1),'')<>'Approved') into allapproved;
 if exists(select 1 from tasks where project_id=p_id) and not exists(select 1 from tasks where project_id=p_id and data->>'status'<>stages->>4) and allapproved then stage=stages->>4;
 elsif exists(select 1 from tasks where project_id=p_id and data->>'status'=stages->>3) or exists(select 1 from deliverables dl where dl.project_id=p_id and (select v.data->>'status' from deliverable_versions v where v.deliverable_id=dl.id order by (v.data->>'createdAt')::timestamptz desc limit 1)='Client Review') then stage=stages->>3;
 elsif exists(select 1 from tasks where project_id=p_id and data->>'status' in (stages->>2,stages->>4)) then stage=stages->>2;
 elsif exists(select 1 from tasks where project_id=p_id and data->>'status'=stages->>1) then stage=stages->>1;else stage=stages->>0;end if;
 update projects set data=jsonb_set(data,'{status}',to_jsonb(stage)) where id=p_id;end$$;
create function public.studio_profile() returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare p profiles;begin select * into p from profiles where id=auth.uid();if not found then if exists(select 1 from studio_owners where user_id=auth.uid()) then return jsonb_build_object('id',auth.uid(),'name','Studio Owner','role','OWNER','initials','SO');end if;raise exception 'Your account has not been provisioned for this studio.';end if;return jsonb_build_object('id',p.id,'name',p.name,'role',p.role,'clientId',p.client_id,'initials',left(p.name,2));end$$;
create function public.studio_bootstrap(p_config jsonb) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin perform pg_advisory_xact_lock(872139);if not exists(select 1 from studio_owners where user_id=auth.uid()) then raise exception 'Owner provisioning required.';end if;if exists(select 1 from studio_settings) then raise exception 'Workspace is already initialized.';end if;if jsonb_array_length(p_config->'workflow')<>5 then raise exception 'Five workflow stages required.';end if;
 insert into profiles(id,name,role) values(auth.uid(),'Studio Owner','OWNER') on conflict(id) do nothing;
 insert into studio_settings values(true,jsonb_build_object('agencyName',p_config->'agency'->>'name','agencyDescription',p_config->'agency'->>'description','email',p_config->'agency'->>'email','address',p_config->'agency'->>'address','currency',p_config->'billing'->>'currency','taxRate',(p_config->'billing'->>'taxRate')::numeric,'hourlyRate',(p_config->'billing'->>'hourlyRate')::numeric,'paymentInstructions',p_config->'billing'->>'paymentInstructions','workflow',p_config->'workflow','services',p_config->'agency'->'services'));end$$;
create function public.studio_team_data() returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare r text;result jsonb;begin r=public.studio_role();if r is null or r='CLIENT' then raise exception 'Team access required.';end if;if not exists(select 1 from studio_settings) then raise exception 'Initialize the studio workspace first.';end if;
 select jsonb_build_object('settings',(select data from studio_settings),'people',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'role',role,'clientId',client_id,'initials',left(name,2))),'[]') from profiles),'clients',(select coalesce(jsonb_agg(data),'[]') from clients c where public.studio_admin() or exists(select 1 from projects p where p.client_id=c.id and studio_project_access(p.id))),'projects',(select coalesce(jsonb_agg(data),'[]') from projects where studio_project_access(id)),'tasks',(select coalesce(jsonb_agg(data),'[]') from tasks where studio_project_access(project_id)),'timeEntries',(select coalesce(jsonb_agg(data),'[]') from time_entries where studio_project_access(project_id)),'timers',(select coalesce(jsonb_agg(data),'[]') from timers where user_id=auth.uid()),'deliverables',(select coalesce(jsonb_agg(data),'[]') from deliverables where studio_project_access(project_id)),'versions',(select coalesce(jsonb_agg(v.data),'[]') from deliverable_versions v join deliverables dl on dl.id=v.deliverable_id where studio_project_access(dl.project_id)),'comments',(select coalesce(jsonb_agg(data),'[]') from comments where studio_project_access(project_id)),'approvals',(select coalesce(jsonb_agg(data),'[]') from approvals where studio_project_access(project_id)),'invoices',(select coalesce(jsonb_agg(data),'[]') from invoices where studio_admin()),'payments',(select coalesce(jsonb_agg(data),'[]') from payments where studio_admin()),'activity',(select coalesce(jsonb_agg(data order by data->>'createdAt' desc),'[]') from activity_logs where studio_admin() or studio_project_access(project_id)),'dismissed',(select coalesce(jsonb_agg(key),'[]') from notification_dismissals where user_id=auth.uid()),'revision',0) into result;return result;end$$;

create function public.studio_action(p_op jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
#variable_conflict use_variable
declare kind text:=p_op->>'type';v jsonb:=p_op->'data';id uuid;pid uuid;cid uuid;tid uuid;request uuid;previous jsonb;settings jsonb;rec jsonb;item jsonb;file jsonb;actor text;stage text;amount numeric;sub numeric;paid numeric;sec integer;ids uuid[];number text;result jsonb:='null';existing boolean;begin
 if public.studio_role() is null or public.studio_role()='CLIENT' then raise exception 'Team access required.';end if;perform pg_advisory_xact_lock(872139);request=(p_op->>'requestId')::uuid;if request is null then raise exception 'Request identifier required.';end if;select operation_requests.result into previous from operation_requests where user_id=auth.uid() and request_id=request;if found then return previous;end if;select data into settings from studio_settings;if settings is null then raise exception 'Initialize workspace first.';end if;select name into actor from profiles where profiles.id=auth.uid();
 if kind in ('client','project','archiveClient','invoice','invoiceStatus','payment','approveTime','settings') then perform studio_require_admin();end if;
 if kind='client' then
  id=coalesce(nullif(v->>'id','')::uuid,gen_random_uuid());existing=exists(select 1 from clients where clients.id=id);perform studio_text(v->>'name','client name',2,140);perform studio_text(v->>'contact','contact',0,100);if coalesce(v->>'email','')<>'' and v->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'Invalid email.';end if;
  select data into rec from clients where clients.id=id;v=jsonb_build_object('id',id,'name',v->>'name','contact',coalesce(v->>'contact',''),'email',coalesce(v->>'email',''),'phone',coalesce(v->>'phone',''),'companyInfo',coalesce(v->>'companyInfo',''),'notes',coalesce(v->>'notes',''),'archived',coalesce((rec->>'archived')::boolean,false),'token',coalesce((rec->>'token')::uuid,gen_random_uuid()),'createdAt',coalesce(rec->>'createdAt',now()::text));insert into clients values(id,v,(v->>'token')::uuid) on conflict on constraint clients_pkey do update set data=excluded.data;perform studio_log(null,case when existing then 'Updated client ' else 'Created client ' end||(v->>'name'));result=to_jsonb(id);
 elsif kind='archiveClient' then id=(p_op->>'id')::uuid;select data into rec from clients where clients.id=id;if rec is null then raise exception 'Client not found.';end if;if not (rec->>'archived')::boolean and exists(select 1 from projects where client_id=id and data->>'status'<>settings->'workflow'->>4) then raise exception 'Complete active projects before archiving.';end if;update clients set data=jsonb_set(data,'{archived}',to_jsonb(not (rec->>'archived')::boolean)) where clients.id=id;perform studio_log(null,'Client archive status changed');
 elsif kind='project' then
  id=coalesce(nullif(v->>'id','')::uuid,gen_random_uuid());cid=(v->>'clientId')::uuid;if not exists(select 1 from clients where clients.id=cid and not (data->>'archived')::boolean) then raise exception 'Active client required.';end if;perform studio_text(v->>'name','project name',2,160);perform studio_num((v->>'budget')::numeric,'budget');perform studio_num((v->>'hourlyRate')::numeric,'hourly rate');if v->>'billing' not in ('Fixed fee','Hourly') or v->>'priority' not in ('Low','Medium','High','Urgent') or not (settings->'workflow') ? (v->>'status') or not (settings->'services') ? (v->>'type') then raise exception 'Invalid project options.';end if;if (v->>'start')::date is null or (v->>'deadline')::date is null or (v->>'deadline')::date<(v->>'start')::date then raise exception 'Invalid project dates.';end if;if jsonb_typeof(v->'members')<>'array' or jsonb_array_length(v->'members')=0 or exists(select 1 from jsonb_array_elements_text(v->'members') member where not exists(select 1 from profiles where profiles.id=member::uuid and role<>'CLIENT')) then raise exception 'Valid project members required.';end if;
  select data into rec from projects where projects.id=id;if rec is not null and (rec->>'clientId')::uuid<>cid then raise exception 'Existing projects cannot change client ownership.';end if;if v->>'status'=settings->'workflow'->>4 then perform studio_sync(id);if not exists(select 1 from projects where projects.id=id and data->>'status'=settings->'workflow'->>4) then raise exception 'Complete tasks and approve deliverables first.';end if;end if;
  v=jsonb_build_object('id',id,'clientId',cid,'name',v->>'name','description',coalesce(v->>'description',''),'type',v->>'type','start',v->>'start','deadline',v->>'deadline','status',v->>'status','priority',v->>'priority','budget',(v->>'budget')::numeric,'billing',v->>'billing','hourlyRate',(v->>'hourlyRate')::numeric,'members',v->'members','notes',coalesce(v->>'notes',''),'art',coalesce((rec->>'art')::int,0),'createdAt',coalesce(rec->>'createdAt',now()::text));insert into projects values(id,cid,v) on conflict on constraint projects_pkey do update set data=excluded.data;delete from project_members where project_id=id;insert into project_members select id,member::uuid from jsonb_array_elements_text(v->'members') member;perform studio_log(id,case when rec is null then 'Project created' when rec->>'deadline'<>v->>'deadline' then 'Project deadline changed' else 'Project updated' end);result=to_jsonb(id);
 elsif kind='task' then
  id=coalesce(nullif(v->>'id','')::uuid,gen_random_uuid());pid=(v->>'projectId')::uuid;perform studio_require_project(pid);perform studio_text(v->>'title','task title',2,160);perform studio_num((v->>'estimatedHours')::numeric,'estimated hours',10000);if not (settings->'workflow') ? (v->>'status') or v->>'priority' not in ('Low','Medium','High','Urgent') or not exists(select 1 from project_members where project_id=pid and user_id=(v->>'assignee')::uuid) then raise exception 'Invalid task stage, priority or assignee.';end if;if coalesce(v->>'deadline','')<>'' then perform (v->>'deadline')::date;end if;if jsonb_array_length(v->'checklist')>40 or jsonb_array_length(v->'attachments')>20 then raise exception 'Too many task items.';end if;select data into rec from tasks where tasks.id=id;if rec is not null and (rec->>'projectId')::uuid<>pid then raise exception 'Task project is immutable.';end if;
  for file in select value from jsonb_array_elements(v->'attachments') loop if coalesce(file->>'path','')='' or split_part(file->>'path','/',1)<>pid::text then raise exception 'Attachment belongs to another project.';end if;if (file->>'size')::numeric>10485760 or coalesce(file->>'type','') not in ('image/png','image/jpeg','image/webp','application/pdf') or coalesce((file->>'size')::numeric,-1)<0 then raise exception 'Invalid attachment.';end if;end loop;
  v=jsonb_build_object('id',id,'projectId',pid,'title',v->>'title','assignee',v->>'assignee','priority',v->>'priority','deadline',coalesce(v->>'deadline',''),'description',coalesce(v->>'description',''),'checklist',coalesce(v->'checklist','[]'),'attachments',coalesce(v->'attachments','[]'),'estimatedHours',(v->>'estimatedHours')::numeric,'status',v->>'status','createdAt',coalesce(rec->>'createdAt',now()::text));insert into tasks values(id,pid,(v->>'assignee')::uuid,v) on conflict on constraint tasks_pkey do update set data=excluded.data;perform studio_sync(pid);perform studio_log(pid,case when rec is null then 'Task added: ' else 'Task updated: ' end||(v->>'title'));result=to_jsonb(id);
 elsif kind in ('moveTask','checklist') then id=(p_op->>'id')::uuid;select project_id,data into pid,rec from tasks where tasks.id=id;if rec is null then raise exception 'Task not found.';end if;perform studio_require_project(pid);if kind='moveTask' then stage=p_op->>'status';if not (settings->'workflow') ? stage then raise exception 'Invalid workflow stage.';end if;update tasks set data=jsonb_set(data,'{status}',to_jsonb(stage)) where tasks.id=id;perform studio_sync(pid);perform studio_log(pid,'Task '||(rec->>'title')||' → '||stage);else update tasks set data=jsonb_set(data,'{checklist}',(select jsonb_agg(case when c->>'id'=p_op->>'itemId' then jsonb_set(c,'{done}',to_jsonb(not (c->>'done')::boolean)) else c end) from jsonb_array_elements(rec->'checklist') c)) where tasks.id=id;end if;
 elsif kind in ('time','startTimer') then
  pid=(v->>'projectId')::uuid;tid=nullif(v->>'taskId','')::uuid;perform studio_require_project(pid);if tid is not null and not exists(select 1 from tasks where tasks.id=tid and project_id=pid) then raise exception 'Task does not belong to project.';end if;perform studio_text(v->>'note','work description',2,2000);id=gen_random_uuid();if kind='time' then sec=(v->>'seconds')::int;if sec is null or sec<1 or sec>2678400 or (v->>'date')::date is null then raise exception 'Invalid duration or date.';end if;v=jsonb_build_object('id',id,'projectId',pid,'taskId',coalesce(tid::text,''),'userId',auth.uid(),'date',v->>'date','seconds',sec,'note',v->>'note','billable',coalesce((v->>'billable')::boolean,false),'approved',false,'createdAt',now());insert into time_entries values(id,pid,tid,auth.uid(),null,v);perform studio_log(pid,'Time entry recorded');else if exists(select 1 from timers where user_id=auth.uid()) then raise exception 'Finish the existing timer first.';end if;v=jsonb_build_object('id',id,'projectId',pid,'taskId',coalesce(tid::text,''),'userId',auth.uid(),'note',v->>'note','billable',coalesce((v->>'billable')::boolean,false),'seconds',0,'startedAt',now());insert into timers values(id,pid,tid,auth.uid(),v);end if;
 elsif kind in ('pauseTimer','resumeTimer','stopTimer') then id=(p_op->>'id')::uuid;select data,project_id,task_id into rec,pid,tid from timers where timers.id=id and user_id=auth.uid();if rec is null then raise exception 'Your timer was not found.';end if;sec=(rec->>'seconds')::int+case when rec->>'startedAt' is not null then greatest(0,floor(extract(epoch from now()-(rec->>'startedAt')::timestamptz)))::int else 0 end;if kind='pauseTimer' then update timers set data=data||jsonb_build_object('seconds',sec,'startedAt',null) where timers.id=id;elsif kind='resumeTimer' then if rec->>'startedAt' is not null then raise exception 'Timer is already running.';end if;update timers set data=data||jsonb_build_object('startedAt',now()) where timers.id=id;else if sec<1 then raise exception 'Track at least one second.';end if;id=gen_random_uuid();v=jsonb_build_object('id',id,'projectId',pid,'taskId',coalesce(tid::text,''),'userId',auth.uid(),'date',to_char(now() at time zone 'Asia/Jakarta','YYYY-MM-DD'),'seconds',sec,'note',rec->>'note','billable',(rec->>'billable')::boolean,'approved',false,'createdAt',now());insert into time_entries values(id,pid,tid,auth.uid(),null,v);delete from timers where timers.id=(p_op->>'id')::uuid;perform studio_log(pid,'Timer stopped and time saved');end if;
 elsif kind='approveTime' then id=(p_op->>'id')::uuid;select data into rec from time_entries where time_entries.id=id and invoice_id is null;if rec is null then raise exception 'Entry not found or already billed.';end if;update time_entries set data=jsonb_set(data,'{approved}',to_jsonb(not (rec->>'approved')::boolean)) where time_entries.id=id;
 elsif kind='deliverable' then id=gen_random_uuid();pid=(v->>'projectId')::uuid;perform studio_require_project(pid);perform studio_text(v->>'title','deliverable title',2,160);perform studio_text(v->>'kind','deliverable type',1,70);v=jsonb_build_object('id',id,'projectId',pid,'title',v->>'title','kind',v->>'kind','createdAt',now());insert into deliverables values(id,pid,v);perform studio_log(pid,'Deliverable created: '||(v->>'title'));result=to_jsonb(id);
 elsif kind='version' then
  id=gen_random_uuid();tid=(v->>'deliverableId')::uuid;select project_id into pid from deliverables where deliverables.id=tid;perform studio_require_project(pid);perform studio_text(v->>'label','version label',1,50);file=v->'file';if (file is null or file='null') and coalesce(v->>'url','')='' then raise exception 'Provide a file or preview URL.';end if;if coalesce(v->>'url','')<>'' and v->>'url' !~ '^https?://' then raise exception 'Invalid preview URL.';end if;if file is not null and file<>'null' then if coalesce(file->>'path','')='' or split_part(file->>'path','/',1)<>pid::text or coalesce(file->>'type','') not in ('image/png','image/jpeg','image/webp','application/pdf') or coalesce((file->>'size')::numeric,-1)<0 or (file->>'size')::numeric>10485760 then raise exception 'Invalid private file.';end if;file=file||jsonb_build_object('url','');end if;if coalesce(v->>'reviewDeadline','')<>'' then perform (v->>'reviewDeadline')::date;end if;
  v=jsonb_build_object('id',id,'deliverableId',tid,'label',v->>'label','file',file,'url',coalesce(v->>'url',''),'status','Draft','submittedAt',null,'reviewDeadline',coalesce(v->>'reviewDeadline',''),'createdAt',clock_timestamp());insert into deliverable_versions values(id,tid,v);update projects set data=jsonb_set(data,'{status}',settings->'workflow'->2) where projects.id=pid and data->>'status'=settings->'workflow'->>4;insert into approvals values(gen_random_uuid(),pid,id,(select client_id from projects where projects.id=pid),jsonb_build_object('id',gen_random_uuid(),'projectId',pid,'versionId',id,'clientId',(select client_id from projects where projects.id=pid),'action',case when (select count(*) from deliverable_versions where deliverable_id=tid)>1 then 'New Version Submitted' else 'Version Created' end,'feedback','','actor',actor,'createdAt',now()));perform studio_log(pid,'New deliverable version created');result=to_jsonb(id);
 elsif kind in ('submit','internalReview') then id=(p_op->>'id')::uuid;select v2.data,v2.deliverable_id,dl.project_id into rec,tid,pid from deliverable_versions v2 join deliverables dl on dl.id=v2.deliverable_id where v2.id=id;perform studio_require_project(pid);if rec is null or rec->>'status'='Approved' or id<>(select v2.id from deliverable_versions v2 where deliverable_id=tid order by (v2.data->>'createdAt')::timestamptz desc limit 1) then raise exception 'Only the latest unapproved version can be submitted.';end if;stage=case when kind='submit' then 'Client Review' else 'Internal Review' end;update deliverable_versions set data=data||jsonb_build_object('status',stage,'submittedAt',case when kind='submit' then to_jsonb(now()) else data->'submittedAt' end) where deliverable_versions.id=id;if kind='submit' then update projects set data=jsonb_set(data,'{status}',settings->'workflow'->3) where projects.id=pid;cid=(select client_id from projects where projects.id=pid);insert into approvals values(gen_random_uuid(),pid,id,cid,jsonb_build_object('id',gen_random_uuid(),'projectId',pid,'versionId',id,'clientId',cid,'action','Submitted for Review','feedback','','actor',actor,'createdAt',now()));perform studio_log(pid,'Deliverable submitted for client review');end if;
 elsif kind='comment' then pid=(v->>'projectId')::uuid;perform studio_require_project(pid);tid=nullif(v->>'taskId','')::uuid;id=nullif(v->>'deliverableId','')::uuid;if tid is not null and not exists(select 1 from tasks where tasks.id=tid and project_id=pid) or id is not null and not exists(select 1 from deliverables where deliverables.id=id and project_id=pid) then raise exception 'Comment target does not belong to project.';end if;perform studio_text(v->>'text','comment',1,3000);if v->>'visibility' not in ('Internal','Client-visible') then raise exception 'Invalid comment visibility.';end if;v=jsonb_build_object('id',gen_random_uuid(),'projectId',pid,'taskId',coalesce(tid::text,''),'deliverableId',coalesce(id::text,''),'visibility',v->>'visibility','text',v->>'text','author',actor,'createdAt',now());insert into comments values((v->>'id')::uuid,pid,id,tid,v->>'visibility',v);perform studio_log(pid,'Added '||lower(v->>'visibility')||' comment');
 elsif kind='invoice' then
  id=gen_random_uuid();pid=(v->>'projectId')::uuid;cid=(v->>'clientId')::uuid;if not exists(select 1 from projects where projects.id=pid and client_id=cid) then raise exception 'Project/client mismatch.';end if;if (v->>'issue')::date is null or (v->>'due')::date is null or (v->>'due')::date<(v->>'issue')::date then raise exception 'Invalid invoice dates.';end if;if jsonb_typeof(v->'items')<>'array' or jsonb_array_length(v->'items') not between 1 and 50 then raise exception 'Invoice items required.';end if;sub=0;for item in select value from jsonb_array_elements(v->'items') loop perform studio_text(item->>'description','line description',1,250);perform studio_num((item->>'quantity')::numeric,'quantity',10000);perform studio_num((item->>'rate')::numeric,'rate');if (item->>'quantity')::numeric<=0 then raise exception 'Quantity must be positive.';end if;sub=sub+round((item->>'quantity')::numeric*(item->>'rate')::numeric);end loop;perform studio_num((v->>'discount')::numeric,'discount',sub);perform studio_num((v->>'taxRate')::numeric,'tax rate',100);if sub-(v->>'discount')::numeric<=0 then raise exception 'Invoice total must be positive.';end if;
  select coalesce(array_agg(value::uuid),array[]::uuid[]) into ids from jsonb_array_elements_text(coalesce(v->'timeIds','[]'));if cardinality(ids)<>(select count(distinct x) from unnest(ids) x) then raise exception 'Duplicate time entries.';end if;if exists(select 1 from unnest(ids) x where not exists(select 1 from time_entries where time_entries.id=x and project_id=pid and invoice_id is null and (data->>'billable')::boolean and (data->>'approved')::boolean)) then raise exception 'Only approved unbilled project time can be invoiced.';end if;if cardinality(ids)>0 then select sum(round((t.data->>'seconds')::numeric/3600*(p.data->>'hourlyRate')::numeric)) into amount from time_entries t join projects p on p.id=t.project_id where t.id=any(ids);if sub<>amount then raise exception 'Hourly invoice value must match approved hours at the project rate.';end if;end if;
  select 'INV-'||extract(year from (v->>'issue')::date)::text||'-'||lpad((coalesce(max(split_part(invoices.number,'-',3)::int),0)+1)::text,4,'0') into number from invoices where invoices.number like 'INV-'||extract(year from (v->>'issue')::date)::text||'-%';
  v=jsonb_build_object('id',id,'token',gen_random_uuid(),'number',number,'clientId',cid,'projectId',pid,'issue',v->>'issue','due',v->>'due','items',v->'items','discount',(v->>'discount')::numeric,'taxRate',(v->>'taxRate')::numeric,'status','DRAFT','notes',coalesce(v->>'notes',''),'timeIds',to_jsonb(ids),'createdAt',now(),'currency',settings->>'currency','agency',jsonb_build_object('name',settings->>'agencyName','email',settings->>'email','address',settings->>'address','paymentInstructions',settings->>'paymentInstructions'));insert into invoices values(id,cid,pid,(v->>'token')::uuid,number,v);for item in select value from jsonb_array_elements(v->'items') loop insert into invoice_items values((item->>'id')::uuid,id,item);end loop;update time_entries set invoice_id=id,data=data||jsonb_build_object('invoicedId',id) where time_entries.id=any(ids);perform studio_log(pid,'Invoice created: '||number);result=to_jsonb(id);
 elsif kind='invoiceStatus' then id=(p_op->>'id')::uuid;select data,project_id into rec,pid from invoices where invoices.id=id;if rec is null then raise exception 'Invoice not found.';end if;stage=p_op->>'status';if stage='SENT' and rec->>'status'='DRAFT' then update invoices set data=jsonb_set(data,'{status}','"SENT"') where invoices.id=id;elsif stage='CANCELLED' and rec->>'status'<>'CANCELLED' and p_op->>'confirmed'='true' and not exists(select 1 from payments where invoice_id=id) then update invoices set data=jsonb_set(data,'{status}','"CANCELLED"') where invoices.id=id;update time_entries set invoice_id=null,data=data-'invoicedId' where invoice_id=id;else raise exception 'Invalid invoice transition. Paid status requires a recorded payment.';end if;perform studio_log(pid,'Invoice status changed: '||stage);
 elsif kind='payment' then id=(v->>'invoiceId')::uuid;select data,project_id into rec,pid from invoices where invoices.id=id;if rec is null or rec->>'status'<>'SENT' then raise exception 'Issued invoice required.';end if;select coalesce(sum((data->>'amount')::numeric),0) into paid from payments where invoice_id=id;amount=studio_num((v->>'amount')::numeric,'payment');if amount<=0 or amount>studio_invoice_total(id)-paid then raise exception 'Payment exceeds balance or is not positive.';end if;if (v->>'date')::date is null then raise exception 'Payment date required.';end if;perform studio_text(v->>'method','method',1,80);v=jsonb_build_object('id',gen_random_uuid(),'invoiceId',id,'amount',amount,'date',v->>'date','method',v->>'method','reference',coalesce(v->>'reference',''),'createdAt',now());insert into payments values((v->>'id')::uuid,id,v);perform studio_log(pid,'Payment recorded for '||(rec->>'number'));
 elsif kind='settings' then
  perform studio_text(v->>'agencyName','agency name',2,140);perform studio_num((v->>'taxRate')::numeric,'tax rate',100);perform studio_num((v->>'hourlyRate')::numeric,'hourly rate');if v->>'currency'<>settings->>'currency' and (exists(select 1 from projects) or exists(select 1 from invoices)) then raise exception 'Currency locked while financial records exist.';end if;if v->>'currency' not in ('IDR','USD','EUR','GBP','SGD') or jsonb_array_length(v->'workflow')<>5 or (select count(distinct value) from jsonb_array_elements_text(v->'workflow'))<>5 then raise exception 'Invalid currency or workflow.';end if;for sec in 0..4 loop perform studio_text(v->'workflow'->>sec,'stage name',1,60);end loop;update tasks set data=jsonb_set(data,'{status}',(select v->'workflow'->stage.n from generate_series(0,4) stage(n) where tasks.data->>'status'=settings->'workflow'->>stage.n));update projects set data=jsonb_set(data,'{status}',(select v->'workflow'->stage.n from generate_series(0,4) stage(n) where projects.data->>'status'=settings->'workflow'->>stage.n));update studio_settings set data=v||jsonb_build_object('services',settings->'services');perform studio_log(null,'Studio settings updated');
 elsif kind='dismiss' then perform studio_text(p_op->>'id','notification',1,200);insert into notification_dismissals values(auth.uid(),p_op->>'id') on conflict do nothing;
 else raise exception 'Unsupported team action.';end if;
 insert into operation_requests values(auth.uid(),request,result);return result;end$$;

create function public.studio_portal(p_token uuid) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare c clients;settings jsonb;begin select * into c from clients where portal_token=p_token and not (data->>'archived')::boolean;if c.id is null or not studio_client_access(c.id) then raise exception 'This client workspace requires its authorized client account.';end if;select data into settings from studio_settings;
 return jsonb_build_object('agency',jsonb_build_object('agencyName',settings->>'agencyName','agencyDescription',settings->>'agencyDescription','email',settings->>'email','currency',settings->>'currency'),'client',jsonb_build_object('id',c.id,'name',c.data->>'name','contact',c.data->>'contact','token',c.portal_token),'projects',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',data->>'name','description',data->>'description','type',data->>'type','deadline',data->>'deadline','status',data->>'status','priority',data->>'priority','art',data->'art')),'[]') from projects where client_id=c.id),'deliverables',(select coalesce(jsonb_agg(dl.data),'[]') from deliverables dl join projects p on p.id=dl.project_id where p.client_id=c.id and exists(select 1 from deliverable_versions v where v.deliverable_id=dl.id and v.data->>'submittedAt' is not null)),'versions',(select coalesce(jsonb_agg(v.data),'[]') from deliverable_versions v join deliverables dl on dl.id=v.deliverable_id join projects p on p.id=dl.project_id where p.client_id=c.id and v.data->>'submittedAt' is not null),'comments',(select coalesce(jsonb_agg(cm.data),'[]') from comments cm join projects p on p.id=cm.project_id where p.client_id=c.id and cm.visibility='Client-visible' and cm.task_id is null),'approvals',(select coalesce(jsonb_agg(a.data),'[]') from approvals a join deliverable_versions v on v.id=a.version_id where a.client_id=c.id and v.data->>'submittedAt' is not null),'invoices',(select coalesce(jsonb_agg(data),'[]') from invoices where client_id=c.id and data->>'status'='SENT'),'payments',(select coalesce(jsonb_agg(pm.data),'[]') from payments pm join invoices i on i.id=pm.invoice_id where i.client_id=c.id and i.data->>'status'='SENT'));end$$;
create function public.studio_client_action(p_token uuid,p_op jsonb) returns void language plpgsql security definer set search_path=public,pg_temp as $$
#variable_conflict use_variable
declare cid uuid;pid uuid;id uuid;dlid uuid;rec jsonb;v jsonb:=p_op->'data';action text;feedback text:='';actor text;begin perform pg_advisory_xact_lock(872139);select clients.id into cid from clients where portal_token=p_token and not (data->>'archived')::boolean;if cid is null or not studio_client_access(cid) then raise exception 'Client access denied.';end if;select name into actor from profiles where profiles.id=auth.uid();
 if p_op->>'type'='comment' then pid=(v->>'projectId')::uuid;if not exists(select 1 from projects where projects.id=pid and client_id=cid) or coalesce(v->>'taskId','')<>'' or v->>'visibility'<>'Client-visible' then raise exception 'Client comment access denied.';end if;dlid=nullif(v->>'deliverableId','')::uuid;if dlid is not null and not exists(select 1 from deliverables dl join deliverable_versions dv on dv.deliverable_id=dl.id where dl.id=dlid and dl.project_id=pid and dv.data->>'submittedAt' is not null) then raise exception 'Deliverable unavailable.';end if;perform studio_text(v->>'text','comment',1,3000);id=gen_random_uuid();v=jsonb_build_object('id',id,'projectId',pid,'deliverableId',coalesce(dlid::text,''),'taskId','','visibility','Client-visible','text',v->>'text','author',actor,'createdAt',now());insert into comments values(id,pid,dlid,null,'Client-visible',v);perform studio_log(pid,'Client added a shared comment');return;
 end if;if p_op->>'type' not in ('view','review') then raise exception 'Unsupported client action.';end if;id=(p_op->>'id')::uuid;select dv.data,dv.deliverable_id,dl.project_id into rec,dlid,pid from deliverable_versions dv join deliverables dl on dl.id=dv.deliverable_id join projects p on p.id=dl.project_id where dv.id=id and p.client_id=cid and dv.data->>'submittedAt' is not null;if rec is null then raise exception 'Submitted client version not found.';end if;
 if p_op->>'type'='view' then if exists(select 1 from approvals where version_id=id and data->>'action'='Client Viewed') then return;end if;action='Client Viewed';else if rec->>'status'<>'Client Review' or id<>(select dv.id from deliverable_versions dv where deliverable_id=dlid order by (dv.data->>'createdAt')::timestamptz desc limit 1) then raise exception 'Only the latest pending version can receive a decision.';end if;if p_op->>'decision'='approve' and p_op->>'confirmed'='true' then action='Approved';elsif p_op->>'decision'='revision' then action='Revision Requested';feedback=studio_text(p_op->>'feedback','revision feedback',5,3000);else raise exception 'Explicit approval confirmation or revision feedback required.';end if;update deliverable_versions set data=jsonb_set(data,'{status}',to_jsonb(action)) where deliverable_versions.id=id;if action='Approved' then perform studio_sync(pid);else update projects set data=jsonb_set(data,'{status}',(select data->'workflow'->2 from studio_settings)) where projects.id=pid;end if;end if;
 insert into approvals values(gen_random_uuid(),pid,id,cid,jsonb_build_object('id',gen_random_uuid(),'projectId',pid,'versionId',id,'clientId',cid,'action',action,'feedback',feedback,'actor',actor,'createdAt',now()));perform studio_log(pid,'Client decision: '||action);end$$;
create function public.studio_invoice(p_token uuid) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare i invoices;begin select * into i from invoices where token=p_token and data->>'status'<>'DRAFT';if i.id is null then raise exception 'Invoice not found or not issued.';end if;return jsonb_build_object('invoice',i.data,'payments',(select coalesce(jsonb_agg(data),'[]') from payments where invoice_id=i.id),'clientName',(select data->>'name' from clients where id=i.client_id),'projectName',(select data->>'name' from projects where id=i.project_id));end$$;
-- Revoke default PUBLIC execution on every helper. Only narrow entrypoints are callable.
do $$declare f record;begin for f in select oid::regprocedure signature from pg_proc where pronamespace='public'::regnamespace and proname like 'studio_%' loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);end loop;end$$;
grant execute on function public.studio_profile(),public.studio_bootstrap(jsonb),public.studio_team_data(),public.studio_action(jsonb),public.studio_portal(uuid),public.studio_client_action(uuid,jsonb) to authenticated;
grant execute on function public.studio_invoice(uuid) to anon,authenticated;
grant execute on function public.studio_project_access(uuid),public.studio_client_access(uuid),public.studio_role() to authenticated;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('studio-files','studio-files',false,10485760,array['image/png','image/jpeg','image/webp','application/pdf']) on conflict(id) do nothing;
create policy studio_file_upload on storage.objects for insert to authenticated with check(bucket_id='studio-files' and studio_project_access((split_part(name,'/',1))::uuid));
create policy studio_file_read on storage.objects for select to authenticated using(bucket_id='studio-files' and (studio_project_access((split_part(name,'/',1))::uuid) or exists(select 1 from public.deliverable_versions dv join public.deliverables dl on dl.id=dv.deliverable_id join public.projects p on p.id=dl.project_id where dv.data->'file'->>'path'=storage.objects.name and dv.data->>'submittedAt' is not null and studio_client_access(p.client_id))));
-- Storage object policies need access through a SECURITY DEFINER predicate instead of private direct tables.
create function public.studio_file_access(p_path text) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select studio_project_access((split_part(p_path,'/',1))::uuid) or exists(select 1 from deliverable_versions dv join deliverables dl on dl.id=dv.deliverable_id join projects p on p.id=dl.project_id where dv.data->'file'->>'path'=p_path and dv.data->>'submittedAt' is not null and studio_client_access(p.client_id))$$;
revoke all on function public.studio_file_access(text) from public;grant execute on function public.studio_file_access(text) to authenticated;
drop policy studio_file_read on storage.objects;
create policy studio_file_read on storage.objects for select to authenticated using(bucket_id='studio-files' and studio_file_access(name));

create function public.studio_identity() returns trigger language plpgsql set search_path=public,pg_temp as $$begin new.data=jsonb_set(new.data,'{id}',to_jsonb(new.id));return new;end$$;
do $$declare t text;begin foreach t in array array['clients','projects','tasks','deliverables','deliverable_versions','comments','approvals','invoices','invoice_items','payments','time_entries','timers','activity_logs'] loop execute format('create trigger identity_data before insert on public.%I for each row execute function public.studio_identity()',t);end loop;end$$;
revoke all on function public.studio_identity() from public,anon,authenticated;

alter table public.projects add constraint required_project_data check(data->>'status' is not null and data->>'type' is not null and data->>'billing' is not null and data->>'priority' is not null and jsonb_typeof(data->'members')='array');
alter table public.tasks add constraint required_task_data check(data->>'status' is not null and data->>'priority' is not null and (data->>'estimatedHours')::numeric>=0 and jsonb_typeof(data->'checklist')='array' and jsonb_typeof(data->'attachments')='array');
